S['CH1411NO'] = [{'k': 'noti', 'ch': 'Mở đầu', 'cap': ('"NƯỚC MÌNH NỢ NGẬP ĐẦU', 'RÚT TIỀN ĐI CON"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'noti': {'gio': '23:10', 'ngay': 'Thứ Ba', 'items': [('Zalo', 'Mẹ', 'Con xem cái này đi, nước mình nợ ngập đầu rồi', (239, 68, 68)), ('Zalo', 'Mẹ', 'Mai mẹ ra rút hết sổ tiết kiệm mua vàng', (239, 68, 68)), ('Tin nhắn', 'Ngân hàng', 'Lãi suất khoản vay của quý khách sẽ được điều chỉnh từ kỳ tới', (255, 196, 0))]}, 'say': 'Mười một giờ đêm, anh Tuấn vừa ru con ngủ thì điện thoại rung liên tục. Mẹ anh gửi một đường link, kèm hai dòng: con xem cái này đi, nước mình nợ ngập đầu rồi. Mai mẹ ra rút hết sổ tiết kiệm mua vàng. Ngay bên dưới là tin nhắn của ngân hàng nơi anh đang vay mua nhà: lãi suất khoản vay của quý khách sẽ được điều chỉnh từ kỳ tới.'}, {'k': 'noti', 'cap': ('"NƯỚC MÌNH NỢ NGẬP ĐẦU', 'RÚT TIỀN ĐI CON"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'noti': {'gio': '23:10', 'ngay': 'Thứ Ba', 'items': [('Zalo', 'Mẹ', 'Con xem cái này đi, nước mình nợ ngập đầu rồi', (239, 68, 68)), ('Zalo', 'Mẹ', 'Mai mẹ ra rút hết sổ tiết kiệm mua vàng', (239, 68, 68)), ('Tin nhắn', 'Ngân hàng', 'Lãi suất khoản vay của quý khách sẽ được điều chỉnh từ kỳ tới', (255, 196, 0))], 'co_san': 3}, 'say': 'Hai tin nhắn, hai nỗi sợ, cùng một câu hỏi: Việt Nam đang nợ bao nhiêu, và khoản nợ đó có chạm vào túi mình không?'}, {'k': 'bignum', 'anh': 'Hanoi skyline night||Hanoi skyline', 'cap': ('NỢ CÔNG VIỆT NAM 2025', 'NHƯNG ĐÂY CHƯA PHẢI CHUYỆN LỚN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 33.3, 'fmt': '{:,.1f}', 'unit': '% GDP', 'top': 'NỢ CÔNG / GDP NĂM 2025', 'sub': 'Khoảng 4,27 triệu tỷ đồng', 'col': (255, 196, 0), 'say': 'Em nói luôn kết quả để anh chị đỡ hồi hộp. Nợ công của Việt Nam năm hai nghìn không trăm hai mươi lăm vào khoảng ba mươi ba phần trăm GDP, thấp hơn rất nhiều so với những gì mẹ anh Tuấn đang lo. Nhưng trong lúc lục số liệu, anh Tuấn tìm ra một khoản nợ khác lớn gần gấp năm lần nợ công, lớn hơn cả GDP cả nước. Và khoản nợ đó nằm ngay trong tờ hợp đồng vay đang để trong ngăn kéo nhà anh.'}, {'k': 'chat', 'ch': 'Chương 1 – Nhà nước nợ bao nhiêu?', 'cap': ('"NỢ BAO NHIÊU', 'MÀ MẸ SỢ THẾ?"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Mẹ', 'tv': 'Đang hoạt động', 'gio': '23:25', 'mau': (56, 189, 248), 'msgs': [('me', 'Mẹ ơi, nợ công mình khoảng 33% GDP thôi'), ('Mẹ', 'Thế là nhiều hay ít hả con?'), ('me', 'Nhiều nước giàu còn cao hơn mình mấy lần mẹ ạ'), ('Mẹ', 'Thế sao người ta bảo sắp vỡ nợ?')]}, 'say': 'Anh Tuấn nhắn lại cho mẹ: mẹ ơi, nợ công mình khoảng ba mươi ba phần trăm GDP thôi. Mẹ hỏi: thế là nhiều hay ít hả con? Anh trả lời: nhiều nước giàu còn cao hơn mình mấy lần mẹ ạ. Mẹ vẫn chưa yên: thế sao người ta bảo sắp vỡ nợ? Câu hỏi đó hợp lý, nên mình cùng xem con số thật.'}, {'k': 'cards', 'anh': 'Hanoi skyline||Ho Chi Minh City skyline', 'cap': ('NỢ CÔNG NĂM 2025', 'TỶ ĐỒNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('4.072.002', 'Nợ Chính phủ vay trực tiếp', '31,7% GDP'), ('202.105', 'Nợ Chính phủ bảo lãnh', 'giảm hơn một nửa từ 2018'), ('41,8 triệu', 'Chia đều mỗi người dân', '102,3 triệu dân, tự tính')], 'say': 'Theo số liệu Bộ Tài chính tổng hợp trên WiData, năm hai nghìn không trăm hai mươi lăm, Chính phủ vay trực tiếp khoảng bốn phẩy không bảy triệu tỷ đồng. Thêm khoảng hai trăm lẻ hai nghìn tỷ nợ do Chính phủ đứng ra bảo lãnh. Cộng lại, nợ công khoảng bốn phẩy hai bảy triệu tỷ đồng. Chia đều cho hơn một trăm lẻ hai triệu dân, mỗi người khoảng bốn mươi mốt phẩy tám triệu đồng. Nghe thì giật mình, nhưng phải đặt cạnh quy mô nền kinh tế mới hiểu.'}, {'k': 'bars', 'anh': 'Ho Chi Minh City skyline night||Hanoi skyline', 'cap': ('NỢ CÔNG / GDP', 'ĐANG GIẢM, KHÔNG PHẢI TĂNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'bars': [('2018', 45.7, (255, 196, 0), '45,7%'), ('2025', 33.3, (34, 197, 94), '33,3%')], 'say': 'Và đây là cú lật đầu tiên. Năm hai nghìn không trăm mười tám, nợ công bằng khoảng bốn mươi lăm phẩy bảy phần trăm GDP. Đến năm hai nghìn không trăm hai mươi lăm chỉ còn khoảng ba mươi ba phẩy ba phần trăm. Nợ Chính phủ vẫn tăng khoảng bốn mươi bảy phần trăm trong bảy năm. Nhưng GDP danh nghĩa tăng tới tám mươi ba phần trăm, nên gánh nợ so với sức kiếm tiền của đất nước nhẹ đi chứ không nặng lên. Đây là số em tự tính, nguồn có trong mô tả.'}, {'k': 'cards', 'anh': 'World map||Blue Marble', 'cap': ('NỢ NƯỚC NGOÀI QUỐC GIA', 'CẢ NHÀ NƯỚC VÀ TƯ NHÂN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('25,6% GDP', 'Nợ nước ngoài năm 2025', 'khoảng 3,29 triệu tỷ đồng'), ('80 NĂM', 'Mỹ: nợ công / GDP cao nhất', 'VnEconomy 2/11/2026')], 'say': 'Còn nợ nước ngoài, tức tiền cả Nhà nước lẫn doanh nghiệp vay từ bên ngoài. Năm hai nghìn không trăm hai mươi lăm, con số này khoảng ba phẩy hai chín triệu tỷ đồng, chừng hai mươi lăm phẩy sáu phần trăm GDP. Trong khi đó, báo VnEconomy ngày hai tháng mười một vừa đưa tin tỷ lệ nợ công so với GDP của Mỹ đã lên mức cao nhất tám mươi năm. Nên nếu chỉ nhìn nợ công, Việt Nam chưa phải nước đáng lo. Mẹ anh Tuấn có thể ngủ yên. Nhưng anh Tuấn thì không.'}, {'k': 'bignum', 'ch': 'Chương 2 – Khoản nợ lớn hơn cả GDP', 'anh': 'Bitexco Financial Tower||Ho Chi Minh City skyline night', 'cap': ('KHOẢN NỢ GẤP 4,8 LẦN', 'KHÔNG PHẢI NỢ CÔNG'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'value': 20.49, 'fmt': '{:,.2f}', 'unit': ' triệu tỷ', 'top': 'TÍN DỤNG TOÀN NỀN KINH TẾ', 'sub': 'Gấp 4,8 lần nợ công', 'col': (239, 68, 68), 'say': 'Khoản nợ khiến anh Tuấn mất ngủ không nằm ở Chính phủ, mà nằm ở ngân hàng. Đó là tiền ngân hàng cho doanh nghiệp và người dân vay. Đến tháng tám năm hai nghìn không trăm hai mươi sáu, tổng dư nợ cho vay của cả nền kinh tế là khoảng hai mươi phẩy bốn chín triệu tỷ đồng. Quy ra đô la theo tỷ giá hôm nay, khoảng bảy trăm chín mươi ba tỷ đô la, gấp khoảng bốn phẩy tám lần toàn bộ nợ công.'}, {'k': 'bars', 'anh': 'Bitexco Financial Tower||Ho Chi Minh City skyline night', 'cap': ('DƯ NỢ CHO VAY / GDP', 'TỰ TÍNH TỪ SỐ NHNN, TCTK'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'bars': [('2016', 97.6, (255, 196, 0), '97,6%'), ('2020', 114.3, (255, 196, 0), '114,3%'), ('2022', 123.9, (239, 68, 68), '123,9%'), ('2024', 135.7, (239, 68, 68), '135,7%'), ('2025', 144.7, (239, 68, 68), '144,7%'), ('8/2026', 145.8, (239, 68, 68), '145,8%')], 'say': 'So với quy mô nền kinh tế, cuối năm hai nghìn không trăm mười sáu dư nợ cho vay bằng khoảng chín mươi bảy phẩy sáu phần trăm GDP. Năm hai nghìn không trăm hai mươi lên một trăm mười bốn phần trăm. Năm hai nghìn không trăm hai mươi bốn khoảng một trăm ba mươi sáu phần trăm. Và đến tháng tám năm nay là khoảng một trăm bốn mươi sáu phần trăm. Tức là cứ nền kinh tế làm ra một trăm đồng mỗi năm, thì đang có khoảng một trăm bốn mươi sáu đồng là tiền đi vay ngân hàng.'}, {'k': 'bars', 'anh': 'Bitexco Financial Tower||Ho Chi Minh City skyline night', 'cap': ('DƯ NỢ CHO VAY / GDP', 'TỰ TÍNH TỪ SỐ NHNN, TCTK'), 'cols': ((255, 255, 255), (239, 68, 68)), 'bars': [('2016', 97.6, (255, 196, 0), '97,6%'), ('2020', 114.3, (255, 196, 0), '114,3%'), ('2022', 123.9, (239, 68, 68), '123,9%'), ('2024', 135.7, (239, 68, 68), '135,7%'), ('2025', 144.7, (239, 68, 68), '144,7%'), ('8/2026', 145.8, (239, 68, 68), '145,8%')], 'say': 'Mười năm, dư nợ tăng gần gấp bốn, còn GDP danh nghĩa chỉ tăng khoảng hai phẩy năm lần.'}, {'k': 'cards', 'anh': 'Bitexco Financial Tower||Ho Chi Minh City skyline night', 'cap': ('TRONG 12 THÁNG QUA', 'TIỀN VAY CHẠY NHANH HƠN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('+17,4%', 'Dư nợ cho vay', 'so với tháng 8/2025'), ('+12,9%', 'Em tự tính', 'GDP danh nghĩa 4 quý'), ('200 triệu', 'Chia đều mỗi người dân', 'gồm cả nợ doanh nghiệp')], 'say': 'Trong mười hai tháng qua, dư nợ cho vay tăng khoảng mười bảy phẩy bốn phần trăm, trong khi GDP danh nghĩa chỉ tăng khoảng mười hai phẩy chín phần trăm. Nợ đang lớn nhanh hơn thu nhập. Nếu chia đều dư nợ đó cho mỗi người dân, kể cả em bé mới sinh, con số là khoảng hai trăm triệu đồng một người. Dĩ nhiên phần lớn là nợ của doanh nghiệp, nhưng nó cho anh chị thấy nền kinh tế đang chạy bằng tiền vay nhiều đến mức nào.'}, {'k': 'giay', 'ch': 'Chương 3 – Tiền vay đi đâu?', 'cap': ('DÒNG CHỮ NHỎ', 'TRONG HỢP ĐỒNG VAY NHÀ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'HỢP ĐỒNG TÍN DỤNG', 'so': 'Khách hàng: Nguyễn Văn Tuấn – vay mua căn hộ', 'dau': 'ĐÃ KÝ', 'dieu': [('Số tiền vay: 1.200.000.000 đồng, thời hạn 20 năm.', '1,2 TỶ'), ('Lãi suất 2 năm đầu: 8%/năm, cố định.', '8%'), ('Sau đó: lãi suất cơ sở cộng biên độ, điều chỉnh 3 tháng một lần.', 'THẢ NỔI')]}, 'say': 'Anh Tuấn mở ngăn kéo, lấy hợp đồng vay ra đọc lại. Vay một phẩy hai tỷ đồng, hai mươi năm, để mua căn hộ chung cư. Hai năm đầu lãi suất tám phần trăm cố định. Sau đó là dòng chữ nhỏ mà lúc ký anh không để ý: lãi suất cơ sở cộng biên độ, điều chỉnh ba tháng một lần. Anh chợt hiểu, khoản vay của mình cũng nằm trong con số hai mươi phẩy năm triệu tỷ kia.'}, {'k': 'cards', 'anh': 'Hanoi apartment buildings||Ho Chi Minh City apartment buildings', 'cap': ('TIỀN VAY DỒN VÀO ĐÂU?', 'THÁNG 8/2026'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('45%', 'Nhóm "dịch vụ khác" trong tổng dư nợ', 'khoảng 9,24 triệu tỷ'), ('+24,4%', 'Nhóm này tăng trong 1 năm', 'tổng dư nợ chỉ +17,4%')], 'say': 'Vậy hai mươi phẩy năm triệu tỷ đó chảy vào đâu? Trong số liệu của Ngân hàng Nhà nước có một nhóm tên khô khan là các hoạt động dịch vụ khác. Phần lớn nhóm này là cho vay kinh doanh bất động sản và cho vay tiêu dùng, mà chủ yếu là vay mua nhà như anh Tuấn. Nhóm này chiếm khoảng bốn mươi lăm phần trăm tổng dư nợ, khoảng chín phẩy hai bốn triệu tỷ đồng. Nó tăng hai mươi bốn phẩy bốn phần trăm chỉ trong một năm, nhanh hơn hẳn mức tăng chung.'}, {'k': 'cards', 'anh': 'Hanoi apartment buildings||Ho Chi Minh City apartment buildings', 'cap': ('TIỀN VAY DỒN VÀO ĐÂU?', 'THÁNG 8/2026'), 'cols': ((255, 255, 255), (239, 68, 68)), 'cards': [('45%', 'Nhóm "dịch vụ khác" trong tổng dư nợ', 'khoảng 9,24 triệu tỷ'), ('+24,4%', 'Nhóm này tăng trong 1 năm', 'tổng dư nợ chỉ +17,4%')], 'say': 'Tiền vay đang dồn về nhà đất.'}, {'k': 'call', 'cap': ('"ANH ĐANG ĐỨNG', 'Ở PHÍA RỦI RO"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'call': {'ten': 'Bạn thân Hải', 'phu': 'Làm tín dụng 10 năm', 'mau': (34, 197, 94), 'loi': ['Ngân hàng cho vay nhanh hơn huy động', 'Thiếu vốn thì lãi suất khó mà giảm']}, 'say': 'Anh Tuấn gọi cho Hải, bạn thân làm tín dụng ở ngân hàng mười năm. Hải nói thẳng: vấn đề không nằm ở việc nước mình vỡ nợ. Vấn đề là ngân hàng đang cho vay nhanh hơn tốc độ họ huy động được tiền. Mà ngân hàng thiếu vốn thì phải trả lãi cao hơn để giữ tiền gửi, và người vay như ông sẽ là người trả phần chênh đó.'}, {'k': 'noti', 'ch': 'Chương 4 – Ngân hàng lấy tiền đâu cho vay?', 'cap': ('NGÂN HÀNG', 'SẮP HẾT ROOM?'), 'cols': ((255, 255, 255), (239, 68, 68)), 'noti': {'gio': '00:15', 'ngay': 'Thứ Tư', 'items': [('Tin tức', 'VietnamFinance 29/10', 'Loạt ngân hàng có thể cạn room tín dụng sau quy định mới', (239, 68, 68)), ('Zalo', 'Hải', 'Ông xem số này: cho vay tăng 17,4%, tiền gửi chỉ 13,6%', (56, 189, 248))]}, 'say': 'Cúp máy, Hải gửi ngay cho anh Tuấn một bài báo. Cuối tháng mười, VietnamFinance đưa tin nhiều ngân hàng có thể cạn hạn mức tín dụng sau quy định mới của Ngân hàng Nhà nước. Kèm theo là một dòng tin nhắn: ông xem số này, cho vay tăng mười bảy phẩy bốn phần trăm, tiền gửi chỉ tăng mười ba phẩy sáu phần trăm.'}, {'k': 'cards', 'anh': 'Bitexco Financial Tower||Ho Chi Minh City skyline night', 'cap': ('CHO VAY VƯỢT TIỀN GỬI', 'TỶ ĐỒNG – EM TỰ TÍNH'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('1.495.911', 'Tháng 8/2025', 'dư nợ trừ tổng tiền gửi'), ('2.717.982', 'Tháng 8/2026', 'gấp 1,8 lần sau 1 năm'), ('+13,6%', 'Tổng tiền gửi tăng', 'dư nợ +17,4%')], 'say': 'Hải nói đúng. Em lấy tổng dư nợ trừ đi tổng tiền gửi trong hệ thống ngân hàng. Tháng tám năm hai nghìn không trăm hai mươi lăm, phần cho vay vượt tiền gửi khoảng một phẩy năm triệu tỷ đồng. Tháng tám năm hai nghìn không trăm hai mươi sáu, con số này là khoảng hai phẩy bảy hai triệu tỷ, gấp một phẩy tám lần chỉ sau một năm. Khi tiền cho vay lớn nhanh hơn tiền gửi, ngân hàng phải đi tìm nguồn vốn khác, thường là đắt hơn.'}, {'k': 'giay', 'cap': ('SỔ TIẾT KIỆM CỦA MẸ', 'LÃI THẬT CÒN BAO NHIÊU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'SỔ TIẾT KIỆM – KỲ HẠN 12 THÁNG', 'so': 'Phép tính anh Tuấn ghi bên lề', 'dau': 'ĐÃ TÍNH', 'dieu': [('Lãi suất 12 tháng, nhóm ngân hàng Nhà nước: 5,4%/năm', '5,4%'), ('Lạm phát tháng 10/2026 so với cùng kỳ: 5,09%', '5,09%'), ('Lãi thật sau lạm phát: khoảng 0,3 điểm %', 'GẦN ĐỨNG YÊN')]}, 'say': 'Còn sổ tiết kiệm của mẹ anh Tuấn thì sao? Lãi suất mười hai tháng ở nhóm ngân hàng thương mại Nhà nước hôm nay là năm phẩy bốn phần trăm mỗi năm. Lạm phát tháng mười so với cùng kỳ là năm phẩy không chín phần trăm. Trừ đi, lãi thật chỉ còn khoảng không phẩy ba điểm phần trăm. Gửi tiền không lỗ, nhưng gần như đứng yên. Và chính vì tiền gửi kém hấp dẫn, ngân hàng càng khó huy động, áp lực lại dồn sang phía người đi vay.'}, {'k': 'cards', 'ch': 'Chương 5 – Lịch sử từng lặp lại', 'anh': 'ov:old banknotes inflation||money inflation', 'cap': ('VIỆT NAM 2007 – 2008', 'KHI TIỀN VAY CHẠY QUÁ NHANH'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('+53,89%', 'Tín dụng năm 2007', 'Ngân hàng Nhà nước'), ('22,97%', 'Lạm phát bình quân 2008', 'Tổng cục Thống kê')], 'say': 'Chuyện tiền vay chạy nhanh hơn nền kinh tế, Việt Nam đã trải qua. Năm hai nghìn không trăm linh bảy, tín dụng tăng năm mươi ba phẩy tám chín phần trăm. Một năm sau, lạm phát bình quân năm hai nghìn không trăm linh tám lên hai mươi hai phẩy chín bảy phần trăm. Ngân hàng Nhà nước buộc phải siết mạnh, lãi suất cho vay có lúc vượt hai mươi phần trăm mỗi năm. Những người vay lãi thả nổi để mua nhà, mua đất lúc đó là những người chịu trận đầu tiên.'}, {'k': 'text', 'cap': ('BÂY GIỜ KHÔNG PHẢI 2008', 'NHƯNG BÀI HỌC VẪN CÒN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'ov:stock chart monitor||candlestick chart', 'say': 'Em nói công bằng: hôm nay không giống năm hai nghìn không trăm linh tám. Tín dụng tăng mười bảy phần trăm chứ không phải năm mươi ba phần trăm, lạm phát khoảng năm phần trăm chứ không phải hai mươi ba. Nhưng bài học vẫn nguyên giá trị: khi tiền vay lớn nhanh hơn thu nhập nhiều năm liền, người trả giá thường không phải Nhà nước, mà là người vay với lãi suất thả nổi.'}, {'k': 'bars', 'ch': 'Chương 6 – Bài toán trong căn hộ', 'anh': 'Hanoi apartment buildings||Ho Chi Minh City apartment buildings', 'cap': ('VAY 1,2 TỶ, 20 NĂM', 'TRIỆU ĐỒNG MỖI THÁNG'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'bars': [('8%', 10.04, (255, 196, 0), '10,04'), ('10%', 11.58, (239, 68, 68), '11,58'), ('11%', 12.39, (239, 68, 68), '12,39')], 'say': 'Anh Tuấn ngồi tính lại khoản vay của mình. Vay một phẩy hai tỷ, trả đều trong hai mươi năm. Lãi tám phần trăm, mỗi tháng trả khoảng mười phẩy không bốn triệu đồng. Nếu lãi lên mười phần trăm, con số thành mười một phẩy năm tám triệu mỗi tháng. Lên mười một phần trăm là mười hai phẩy ba chín triệu mỗi tháng.'}, {'k': 'cards', 'anh': 'Hanoi apartment buildings||Ho Chi Minh City apartment buildings', 'cap': ('CHỈ 2 ĐIỂM % LÃI SUẤT', 'CÁI GIÁ CỦA DÒNG CHỮ NHỎ'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('1,54 triệu', 'Trả thêm mỗi tháng', 'lãi từ 8% lên 10%'), ('371 triệu', 'Em tự tính, trả đều 240 tháng', 'trả thêm sau 20 năm'), ('9,18 triệu', 'Thu nhập bình quân lao động', 'mỗi tháng, quý 3/2026')], 'say': 'Chỉ hai điểm phần trăm lãi suất thôi, anh Tuấn trả thêm khoảng một phẩy năm tư triệu đồng mỗi tháng, gần mười tám phẩy năm triệu mỗi năm. Cộng cả hai mươi năm là thêm khoảng ba trăm bảy mươi mốt triệu đồng. Để dễ hình dung, thu nhập bình quân của người lao động quý ba năm nay là chín phẩy một tám triệu đồng mỗi tháng. Một phẩy năm tư triệu bằng khoảng mười bảy phần trăm số đó.'}, {'k': 'chat', 'cap': ('PHƯƠNG ÁN KHÁC', 'HAI VỢ CHỒNG TỰ VẠCH RA'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Vợ', 'tv': 'Đang hoạt động', 'gio': '00:40', 'mau': (34, 197, 94), 'msgs': [('me', 'Mình trả bớt 200 triệu gốc trước khi hết ưu đãi nhé'), ('me', 'Còn 1 tỷ thì lãi 10% cũng chỉ 9,65 triệu mỗi tháng'), ('Vợ', 'Ừ, nhưng phải giữ lại đủ 6 tháng tiền trả nợ đấy'), ('me', 'Và tổng trả nợ không quá 40% lương hai đứa')]}, 'say': 'Anh Tuấn không hoảng như mẹ. Anh nhắn cho vợ một phương án khác. Một: dồn khoản tiết kiệm trả bớt hai trăm triệu nợ gốc trước khi hết ưu đãi. Vay còn một tỷ, kể cả lãi mười phần trăm cũng chỉ trả khoảng chín phẩy sáu lăm triệu mỗi tháng, thấp hơn mức hiện tại. Hai: giữ tổng tiền trả nợ không quá bốn mươi phần trăm thu nhập cả nhà. Ba, vợ anh nhắc thêm: luôn để sẵn quỹ dự phòng đủ sáu tháng trả nợ, thay vì rút hết đi mua vàng theo lời đồn.'}, {'k': 'chat', 'cap': ('PHƯƠNG ÁN KHÁC', 'HAI VỢ CHỒNG TỰ VẠCH RA'), 'cols': ((255, 255, 255), (255, 196, 0)), 'chat': {'ten': 'Vợ', 'tv': 'Đang hoạt động', 'gio': '00:40', 'mau': (34, 197, 94), 'msgs': [('me', 'Mình trả bớt 200 triệu gốc trước khi hết ưu đãi nhé'), ('me', 'Còn 1 tỷ thì lãi 10% cũng chỉ 9,65 triệu mỗi tháng'), ('Vợ', 'Ừ, nhưng phải giữ lại đủ 6 tháng tiền trả nợ đấy'), ('me', 'Và tổng trả nợ không quá 40% lương hai đứa')], 'co_san': 4}, 'say': 'Đây là cách anh Tuấn tự tính cho nhà mình, không phải lời khuyên chung cho mọi người.'}, {'k': 'checklist', 'ch': 'Chương 7 – Nhà đầu tư đọc con số này thế nào?', 'anh': 'ov:stock chart monitor||candlestick chart', 'cap': ('3 CÂU HỎI', 'KHI NGHE "VIỆT NAM NỢ NHIỀU"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Nợ của ai: Nhà nước hay tư nhân?', (34, 197, 94)), ('Doanh nghiệp mình giữ vay nhiều không?', (34, 197, 94)), ('Lãi suất 6–12 tháng tới đi đâu?', (255, 196, 0))], 'say': 'Với nhà đầu tư chứng khoán, em gợi ý ba câu hỏi mỗi khi nghe ai đó nói Việt Nam nợ nhiều. Một: nợ của ai, Nhà nước, doanh nghiệp hay hộ gia đình? Mỗi loại có rủi ro rất khác nhau. Hai: doanh nghiệp mình đang nắm giữ vay nhiều không, và chi phí lãi vay đang ăn mất bao nhiêu phần lợi nhuận? Ba: khi cho vay chạy nhanh hơn tiền gửi, lãi suất sáu đến mười hai tháng tới sẽ đi về đâu?'}, {'k': 'checklist', 'anh': 'ov:stock chart monitor||candlestick chart', 'cap': ('3 CÂU HỎI', 'KHI NGHE "VIỆT NAM NỢ NHIỀU"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'items': [('Nợ của ai: Nhà nước hay tư nhân?', (34, 197, 94)), ('Doanh nghiệp mình giữ vay nhiều không?', (34, 197, 94)), ('Lãi suất 6–12 tháng tới đi đâu?', (255, 196, 0))], 'say': 'Anh chị có thể tra nợ vay, chi phí lãi vay và lợi nhuận từng quý của hơn bốn trăm mã miễn phí trên chứng khoán Huy Nguyễn chấm com.'}, {'k': 'chat', 'ch': 'Kết – Tin nhắn lúc 1 giờ sáng', 'cap': ('"MẸ ĐỪNG RÚT TIỀN', 'NHÀ MÌNH CẦN XEM LẠI KHOẢN VAY"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Mẹ', 'tv': 'Đang hoạt động', 'gio': '01:05', 'mau': (56, 189, 248), 'msgs': [('me', 'Mẹ đừng rút sổ tiết kiệm nhé, nước mình chưa vỡ nợ đâu'), ('me', 'Cái con lo là khoản vay nhà mình'), ('Mẹ', 'Vậy mẹ để sổ đó, khi nào con cần thì lấy trả bớt nợ')]}, 'say': 'Một giờ sáng, anh Tuấn nhắn cho mẹ: mẹ đừng rút sổ tiết kiệm nhé, nước mình chưa vỡ nợ đâu. Cái con lo là khoản vay nhà mình. Một lúc sau mẹ trả lời: vậy mẹ cứ để sổ đó, khi nào con cần thì lấy trả bớt nợ. Đôi khi câu hỏi đáng sợ nhất không phải đất nước nợ bao nhiêu, mà là gia đình mình nợ bao nhiêu.'}, {'k': 'end', 'cap': ('NẾU LÃI VAY LÊN 11%', 'ANH CHỊ SẼ LÀM GÌ?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Còn anh chị, nếu lãi vay nhà mình lên mười một phần trăm, anh chị sẽ trả bớt nợ, bán bớt tài sản, hay cứ giữ nguyên? Kể cho em và mọi người ở phần bình luận nhé. Nếu thấy video hữu ích, anh chị đăng ký kênh để xem những câu hỏi lớn tiếp theo.'}]
META = {'CH1411NO': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Câu hỏi lớn', 'ngay': '2026-11-14', 'gio_goi_y': '12:00', 'gio': '12:00', 'nhac': 'lofi', 'tieu_de': 'Việt Nam Đang Nợ Bao Nhiêu? Nợ Công Chỉ 33% GDP, Nhưng Khoản Vay 146% GDP Mới Chạm Vào Túi Anh Chị', 'title': 'Việt Nam Đang Nợ Bao Nhiêu? Nợ Công Chỉ 33% GDP, Nhưng Khoản Vay 146% GDP Mới Chạm Vào Túi Anh Chị', 'mo_ta': "Nợ công Việt Nam năm 2025 chỉ khoảng 33% GDP và đang giảm. Nhưng tổng dư nợ cho vay của nền kinh tế đã khoảng 20,5 triệu tỷ đồng, bằng 146% GDP, gấp 4,8 lần nợ công, và tăng nhanh hơn cả thu nhập lẫn tiền gửi. Câu chuyện của một gia đình: người mẹ sợ nước vỡ nợ, người con đang vay 1,2 tỷ mua nhà với lãi suất thả nổi.\n\nNguồn số liệu (Bộ Tài chính, NHNN, Tổng cục Thống kê – tổng hợp WiData):\n• Nợ Chính phủ 2025: 4.072.002 tỷ đồng; nợ Chính phủ bảo lãnh: 202.105 tỷ; GDP danh nghĩa 2025: 12.847.571 tỷ → nợ công 33,3% GDP (tự tính); 2018: 45,7% GDP (tự tính)\n• Nợ nước ngoài quốc gia 2025: 3.286.569 tỷ đồng (25,6% GDP, tự tính); dân số 2025: 102,3 triệu người\n• Tổng dư nợ tín dụng 8/2026: 20.489.434 tỷ đồng (+17,4% so cùng kỳ); khoảng 793 tỷ USD theo tỷ giá 25.840 (11/11/2026)\n• Dư nợ / GDP 4 quý (tự tính): 2016 97,6% · 2020 114,3% · 2022 123,9% · 2024 135,7% · 2025 144,7% · 8/2026 145,8%\n• Tín dụng 'các hoạt động dịch vụ khác' (phần lớn kinh doanh bất động sản và tiêu dùng) 8/2026: 9.238.445 tỷ (45% tổng dư nợ), +24,4% so 8/2025\n• Dư nợ trừ tổng tiền gửi (tự tính): 8/2025 1.495.911 tỷ → 8/2026 2.717.982 tỷ; tổng tiền gửi +13,6% so cùng kỳ\n• Lãi suất huy động 12 tháng NHTM Nhà nước 11/11/2026: 5,4%; CPI 10/2026: +5,09%; thu nhập bình quân lao động Q3/2026: 9,18 triệu đồng mỗi tháng\n• Năm 2007 tín dụng tăng 53,89% (NHNN); lạm phát bình quân 2008: 22,97% (TCTK)\n• Tin: VietnamFinance 29/10/2026 – nhiều ngân hàng có thể cạn room tín dụng; VnEconomy 2/11/2026 – nợ công/GDP của Mỹ cao nhất 80 năm\n• Khoản vay minh hoạ (tự tính, trả đều 240 tháng): 1,2 tỷ lãi 8% = 10,04 triệu mỗi tháng; 10% = 11,58 triệu; 11% = 12,39 triệu\n\nTra nợ vay, chi phí lãi vay, lợi nhuận từng quý 400+ mã: https://chungkhoanhuynguyen.com\nCần trao đổi riêng về danh mục: Zalo 0365.188.286\n\nNhân vật anh Tuấn, mẹ anh và bạn Hải là hư cấu; số liệu là thật.\nChia sẻ góc nhìn, không phải khuyến nghị mua bán.", 'tags': ['nợ công Việt Nam', 'Việt Nam nợ bao nhiêu', 'tín dụng', 'lãi suất vay mua nhà', 'kinh tế Việt Nam', 'nợ công', 'vĩ mô', 'lãi suất thả nổi', 'tín dụng bất động sản'], 'bia_hook': ['NỢ 146% GDP', 'AI ĐANG VAY?'], 'badge': 'NỢ CÔNG CHỈ 33% GDP', 'bia_anh': 'Bitexco Financial Tower||Ho Chi Minh City skyline night', 'bia_hook_b': ['VAY 793 TỶ USD', 'ĐI ĐÂU HẾT?'], 'badge_b': 'CÂU HỎI LỚN', 'bia_hook_c': ['NỢ CÔNG 33%', 'SAO VẪN LO?'], 'badge_c': 'THÁNG 8/2026', 'reel_hook': 'VIỆT NAM NỢ BAO NHIÊU|NỢ THẬT NẰM Ở ĐÂU???', 'fb_post': 'Việt Nam đang nợ bao nhiêu? 💸\n\n👉 Nợ công chỉ khoảng 33% GDP và đang giảm\n👉 Nhưng dư nợ cho vay cả nền kinh tế đã 146% GDP, gấp 4,8 lần nợ công\n👉 Cho vay tăng 17,4%, tiền gửi chỉ 13,6%\n\n🎬 Xem đầy đủ: {LINK}', 'chuong': ['Mở đầu', 'Chương 1 – Nhà nước nợ bao nhiêu?', 'Chương 2 – Khoản nợ lớn hơn cả GDP', 'Chương 3 – Tiền vay đi đâu?', 'Chương 4 – Ngân hàng lấy tiền đâu cho vay?', 'Chương 5 – Lịch sử từng lặp lại', 'Chương 6 – Bài toán trong căn hộ', 'Chương 7 – Nhà đầu tư đọc con số này thế nào?', 'Kết – Tin nhắn lúc 1 giờ sáng']}}
